import java.util.Optional;

public class Main {
    public static void main(String[] args) {
        Optional<String> o = Optional.of("java");
        System.out.println(o.map(s -> s.length()).orElse(0));
    }
}

import java.util.Optional;

public class Main {
    public static void main(String[] args) {
        Optional<Integer> umur = Optional.of(15);
        System.out.println(umur.filter(u -> u >= 17).isPresent());
    }
}

