import java.util.Optional;

public class Main {
    public static void main(String[] args) {
        System.out.println(cariHarga("kopi").orElse(0));
        System.out.println(cariHarga("teh").orElse(0));
        cariHarga("kopi").ifPresent(h -> System.out.println("Kopi tersedia"));
    }

    static Optional<Integer> cariHarga(String barang) {
        if (barang.equals("kopi")) {
            return Optional.of(15000);
        }
        return Optional.empty();
    }
}

